{
  "type": "minecraft:sequence",
  "sequence": [
    {
      "type": "minecraft:condition",
      "if_true": {
        "type": "minecraft:above_preliminary_surface"
      },
      "then_run": {
        "type": "minecraft:sequence",
        "sequence": [
          {
            "type": "minecraft:condition",
            "if_true": {
              "type": "minecraft:biome",
              "biome_is": [
                "northstar:martian_highlands"
              ]
            },
            "then_run": {
              "type": "minecraft:condition",
              "if_true": {
                "type": "minecraft:noise_threshold",
                "noise": "minecraft:badlands_surface",
                "min_threshold": 0.35,
                "max_threshold": 0.8
              },
              "then_run": {
                "type": "minecraft:condition",
                "if_true": {
                  "type": "minecraft:stone_depth",
                  "offset": 4,
                  "surface_type": "floor",
                  "add_surface_depth": false,
                  "secondary_depth_range": 0
                },
                "then_run": {
                  "type": "minecraft:block",
                  "result_state": {
                    "Name": "northstar:mars_gravel"
                  }
                }
              }
            }
          },
          {
            "type": "minecraft:condition",
            "if_true": {
              "type": "minecraft:biome",
              "biome_is": [
                "northstar:martian_dunes"
              ]
            },
            "then_run": {
              "type": "minecraft:condition",
              "if_true": {
                "type": "minecraft:stone_depth",
                "offset": 4,
                "surface_type": "floor",
                "add_surface_depth": false,
                "secondary_depth_range": 0
              },
              "then_run": {
                "type": "minecraft:condition",
                "if_true": {
                  "type": "minecraft:water",
                  "offset": 0,
                  "surface_depth_multiplier": 0,
                  "add_stone_depth": false
                },
                "then_run": {
                  "type": "minecraft:block",
                  "result_state": {
                    "Name": "northstar:mars_sand"
                  }
                }
              }
            }
          },
          {
            "type": "minecraft:condition",
            "if_true": {
              "type": "minecraft:biome",
              "biome_is": [
                "northstar:martian_peaks"
              ]
            },
            "then_run": {
              "type": "minecraft:condition",
              "if_true": {
                "type": "minecraft:stone_depth",
                "offset": 3,
                "surface_type": "floor",
                "add_surface_depth": false,
                "secondary_depth_range": 0
              },
              "then_run": {
                "type": "minecraft:block",
                "result_state": {
                  "Name": "minecraft:snow_block"
                }
              }
            }
          },
          {
            "type": "minecraft:condition",
            "if_true": {
              "type": "minecraft:biome",
              "biome_is": [
                "northstar:martian_dunes"
              ]
            },
            "then_run": {
              "type": "minecraft:condition",
              "if_true": {
                "type": "minecraft:stone_depth",
                "offset": 4,
                "surface_type": "floor",
                "add_surface_depth": false,
                "secondary_depth_range": 0
              },
              "then_run": {
                "type": "minecraft:condition",
                "if_true": {
                  "type": "minecraft:water",
                  "offset": 0,
                  "surface_depth_multiplier": 0,
                  "add_stone_depth": false
                },
                "then_run": {
                  "type": "minecraft:block",
                  "result_state": {
                    "Name": "northstar:mars_sand"
                  }
                }
              }
            }
          },
          {
            "type": "minecraft:condition",
            "if_true": {
              "type": "minecraft:biome",
              "biome_is": [
                "northstar:martian_highlands"
              ]
            },
            "then_run": {
              "type": "minecraft:condition",
              "if_true": {
                "type": "minecraft:stone_depth",
                "offset": 4,
                "surface_type": "floor",
                "add_surface_depth": false,
                "secondary_depth_range": 0
              },
              "then_run": {
                "type": "minecraft:condition",
                "if_true": {
                  "type": "minecraft:water",
                  "offset": 0,
                  "surface_depth_multiplier": 0,
                  "add_stone_depth": false
                },
                "then_run": {
                  "type": "minecraft:block",
                  "result_state": {
                    "Name": "northstar:mars_soil"
                  }
                }
              }
            }
          }
        ]
      }
    }
  ]
}
